   722	func initializeSemanticSQLite(db *sql.DB) error {
   723		statements := []string{
   724			`PRAGMA journal_mode=WAL`,
   725			`CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)`,
   726			`CREATE TABLE files (path TEXT PRIMARY KEY, blob TEXT, content_hash TEXT)`,
   727			`CREATE TABLE symbols (id TEXT PRIMARY KEY, kind TEXT, name TEXT, qualified_name TEXT, file_path TEXT, start_line INTEGER, end_line INTEGER, signature TEXT, language TEXT, stable_id_version TEXT)`,
   728			`CREATE TABLE relations (id INTEGER PRIMARY KEY AUTOINCREMENT, from_id TEXT NOT NULL, to_id TEXT NOT NULL, type TEXT NOT NULL, confidence REAL, reason TEXT, warning_codes TEXT)`,
   729			`CREATE TABLE reverse_relations (to_id TEXT NOT NULL, from_id TEXT NOT NULL, type TEXT NOT NULL)`,
   730			`CREATE INDEX idx_symbols_name ON symbols(name)`,
   731			`CREATE INDEX idx_symbols_qualified_name ON symbols(qualified_name)`,
   732			`CREATE INDEX idx_symbols_file_path ON symbols(file_path)`,
   733			`CREATE INDEX idx_relations_from ON relations(from_id)`,
   734			`CREATE INDEX idx_relations_to ON relations(to_id)`,
   735			`CREATE INDEX idx_reverse_to ON reverse_relations(to_id)`,
   736			`CREATE TABLE symbol_fts (id TEXT PRIMARY KEY, text TEXT NOT NULL)`,
   737			`CREATE TABLE parse_cache (path TEXT PRIMARY KEY, blob TEXT, content_hash TEXT, artifact_path TEXT NOT NULL)`,
   738			`CREATE TABLE warnings (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT, severity TEXT, path TEXT, effect TEXT, detail TEXT, source TEXT)`,
   739			`CREATE TABLE metrics (key TEXT PRIMARY KEY, value TEXT NOT NULL)`,
   740		}
   741		for _, statement := range statements {
   742			if _, err := db.Exec(statement); err != nil {
